int maxActivities(vector<int> start, vector<int> finish, int n) {
    vector<pair<int,int>> arr(n);
    for(int i=0; i<n; i++) arr[i] = {finish[i], start[i]};
    sort(arr.begin(), arr.end());
    int count = 1;
    int limit = arr[0].first;
    for(int i=1; i<n; i++) {
        if(arr[i].second >= limit) {
            count++;
            limit = arr[i].first;
        }
    }
    return count;
}

