public int maxActivities(int start[], int finish[], int n) {
    int[][] arr = new int[n][2];
    for(int i=0; i<n; i++) { arr[i][0] = finish[i]; arr[i][1] = start[i]; }
    Arrays.sort(arr, (a, b) -> a[0] - b[0]);
    int count = 1, limit = arr[0][0];
    for(int i=1; i<n; i++) {
        if(arr[i][1] >= limit) {
            count++;
            limit = arr[i][0];
        }
    }
    return count;
}

